class @derive(eq, print) Student = Class() {
    string @public name;
    vector<int> @public marks;
}

function[<Student>|<float>] average_of = Function(Student student) {
    if (student.marks.isEmpty()) {
        return 0.0;
    }
    return round(student.marks.average(), 1);
}

function[<>|<>] @test average_of_example = Function() {
    ensure(average_of(Student("Ria", [80, 90])) == 85.0, "Ria's average should be 85.0");
}

function[<float>|<string>] grade_for = Function(float average) {
    if (average >= TOP_GRADE) { return "A"; }
    if (average >= 75) { return "B"; }
    if (average >= PASS_MARK) { return "C"; }
    return "F";
}

function[<vector<Student>>|<>] class_report = Function(vector<Student> students) {
    int passed = 0;
    repeat(auto s in students) {
        float avg = average_of(s);
        string grade = grade_for(avg);
        print(f"{s.name:<6} {avg:>5.1} {grade}");
        if (grade != "F") {
            passed += 1;
        }
    }
    print(f"{passed} of {students.size()} passed");
}

function[<vector<int>>|<bool>] marks_are_valid = Function(vector<int> marks) {
    return marks.all(currVal >= 0 and currVal <= 100);
}

function[<>|<>] @test top_student_gets_an_a = Function() {
    ensure(grade_for(average_of(Student("Top", [95, 92]))) == "A", "95 and 92 should be an A");
}

function[<>|<>] @entry main = Function() {
    vector<Student> students = [
        Student("Sam", [95, 88]),
        Student("Ria", [72, 65, 80]),
        Student("Tom", [30, 45])
    ];
    repeat(auto s in students) {
        ensure(marks_are_valid(s.marks), f"{s.name} has a mark outside 0 to 100");
    }
    class_report(students);
}
